struct user_entry {
    boost::flyweight<std::string> first_name;   // shared, immutable
    boost::flyweight<std::string> last_name;
    int age;                                    // extrinsic state
};
user_entry u("Ada", "Lovelace", 36);
bool same = u.first_name == user_entry("Ada", "X", 1).first_name;
// flyweight<T> converts to const T&; equality compares handles, not strings.

