using Pool = std::unordered_map<std::string, std::shared_ptr<const Glyph>>;

std::shared_ptr<const Glyph> glyph_for(Pool &pool, std::string_view name) {
    if (auto it = pool.find(std::string(name)); it != pool.end())
        return it->second;                        // canonical instance
    auto g = std::make_shared<const Glyph>(name); // built once, const handle
    pool.emplace(std::string(name), g);
    return g;
}
